import java.util.Scanner;

public class Main {
    static final long MODULUS = 1000000007;

    static int fastPow(int base, int power) {
        if (power == 1) return base;
        int halfPow = fastPow(base, power / 2);
        long res = (1L * halfPow * halfPow) % MODULUS;
        if (power % 2 == 0) {
            return (int) res;
        } else {
            return (int) ((res * base) % MODULUS);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_value = sc.nextInt();
        int k_value = sc.nextInt();

        if (k_value == 0) {
            System.out.println(fastPow(p_value, p_value - 1));
            return;
        }

        if (k_value == 1) {
            System.out.println(fastPow(p_value, p_value));
            return;
        }

        int count = 1;
        int t_value = k_value;
        while (true) {
            count++;
            t_value = (int) ((1L * t_value * k_value) % p_value);
            if (t_value == 1) {
                System.out.println(fastPow(p_value, (p_value - 1) / count));
                return;
            }
        }
    }
}
